async function fishRaw(count) {
  const start = Date.now();
  let prevCount = 0;
  while (Date.now() - start < 120000) {
    await dismiss();
    const s = sdk.getState();
    if (Math.abs(s.player.worldX - FISH.x) > 8 || Math.abs(s.player.worldZ - FISH.z) > 8) {
      await bot.walkTo(FISH.x, FISH.z); await new Promise(r => setTimeout(r, 500)); continue;
    }
    const spot = s.nearbyNpcs?.find(n => /fishing\s*spot/i.test(n.name));
    if (!spot) { await new Promise(r => setTimeout(r, 500)); continue; }
    const netOpt = spot.optionsWithIndex?.find(o => /^net$/i.test(o.text));
    if (!netOpt) continue;
